from pathlib import Path
from collections import defaultdict, Counter, OrderedDict
import urllib.request, json, math, hashlib, time
root=Path('/work/targetmol/run/agent/project/input_targets')
out=Path('/work/targetmol/run/agent/project/experiments/public_pdbs')
out.mkdir(parents=True, exist_ok=True)
candidates={
 'target1':['4HW2','4HW3','4HW4','4ZBF','4ZBI','5W89','5FDO','5W8F'],
 'target2':['3ZON','4OLI','4WOV','5C01','5C03','5TKD','6NSL','6NZE','5WEV'],
 'target3':['7XZ5','7XZ6','8VHF','8ZR5','8ZRK','9L79','9L80','7WCM'],
}
AA={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','SEC':'U','PYL':'O','MSE':'M'}
ignore={'HOH','WAT','DOD','NA','K','CL','CA','MG','ZN','MN','SO4','PO4','GOL','EDO','DMS','ACT'}

def fetch(entry):
    p=out/f'{entry}.pdb'
    if not p.exists():
        url=f'https://files.rcsb.org/download/{entry}.pdb'
        req=urllib.request.Request(url, headers={'User-Agent':'targetmol-bounded-agent/1.0'})
        with urllib.request.urlopen(req, timeout=30) as resp:
            p.write_bytes(resp.read())
        time.sleep(0.2)
    return p

def parse_atoms(path, only_atom=True):
    chains=defaultdict(list); residues=defaultdict(list); seen=set(); hets=Counter(); het_instances=defaultdict(set)
    for line in path.read_text(errors='replace').splitlines():
        rec=line[:6].strip()
        if rec=='ATOM':
            chain=line[21].strip() or '_'; name=line[12:16].strip(); res=line[17:20].strip(); resseq=line[22:26].strip(); icode=line[26].strip()
            try: xyz=(float(line[30:38]), float(line[38:46]), float(line[46:54]))
            except: continue
            chains[chain].append((name,res,resseq,icode,xyz))
            key=(chain,resseq,icode,res)
            if key not in seen:
                seen.add(key); residues[chain].append((resseq,icode,res))
        elif rec=='HETATM':
            res=line[17:20].strip(); chain=line[21].strip() or '_'; resseq=line[22:26].strip(); icode=line[26].strip()
            if res not in ignore:
                hets[res]+=1; het_instances[res].add((chain,resseq,icode))
    return chains,residues,hets,het_instances

def chain_seq(reslist): return ''.join(AA.get(r[2],'X') for r in reslist)

def local(path):
    return parse_atoms(path)

def rmsd(a,b):
    if len(a)"'!=len(b): return None
    s=0.0; n=0
    for x,y in zip(a,b):
        if x[0]!=y[0] or x[1]!=y[1] or x[2]!=y[2]:
            # still compare coords but mark? continue
            pass
        dx=x[4][0]-y[4][0]; dy=x[4][1]-y[4][1]; dz=x[4][2]-y[4][2]
        s+=dx*dx+dy*dy+dz*dz; n+=1
    return (s/n)**0.5 if n else None

all_results={}
for target, entries in candidates.items():
    lchains,lres,_,_=local(root/f'"'{target}.pdb')
    lchain=list(lchains.keys())[0]; lseq=chain_seq(lres[lchain]); latoms=lchains[lchain]
    res=[]
    for entry in entries:
        try:
            p=fetch(entry)
            chains,residues,hets,het_inst=parse_atoms(p)
            best=None
            for ch, atoms in chains.items():
                seq=chain_seq(residues[ch])
                if len(seq)==len(lseq):
                    # simple identity if equal length
                    ident=sum(1 for a,b in zip(seq,lseq) if a==b)/len(lseq) if lseq else 0
                else:
                    # substring identity for target fragment
                    ident=0
                    if lseq in seq or seq in lseq:
                        ident=min(len(seq),len(lseq))/max(len(seq),len(lseq))
                r=None
                if len(atoms)==len(latoms) and seq==lseq:
                    r=rmsd(latoms, atoms)
                item={'entry':entry,'chain':ch,'atom_count':len(atoms),'res_count':len(residues[ch]),'identity':round(ident,4),'rmsd_same_order':None if r is None else round(r,4)}
                if best is None or (item['identity'], -(item['rmsd_same_order'] or 1e9)) > (best['identity'], -(best['rmsd_same_order'] or 1e9)):
                    best=item
            res.append({'entry':entry,'best_chain':best,'ligand_codes':dict(hets),'ligand_instances':{k:len(v) for k,v in het_inst.items()}})
        except Exception as e:
            res.append({'entry':entry,'error':f'{type(e).__name__}: {e}'[:200]})
    all_results[target]=res
(Path('/work/targetmol/run/agent/project/experiments/public_pdbs/match_summary.json')).write_text(json.dumps(all_results,indent=2,sort_keys=True),encoding='utf-8')
for target, rows in all_results.items():
    print('\\n'+target)
    for r in rows:
        print(json.dumps(r, sort_keys=True))
