/bin/bash -lc "/opt/conda/bin/python - <<'PY'
from rdkit import Chem
from rdkit.Chem import Descriptors, Crippen, rdMolDescriptors, Lipinski, QED
import json, sys
from pathlib import Path
# load sascorer if available
try:
    from rdkit.Chem import RDConfig
    sys.path.append(str(Path(RDConfig.RDContribDir)/'SA_Score'))
    import sascorer
except Exception:
    sascorer=None
lig=json.loads(Path('experiments/public_pdbs/chemcomp_ligands.json').read_text())
for code,v in lig.items():
    smi=v.get('smiles')
    if not smi: continue
    m=Chem.MolFromSmiles(smi)
    if not m:
        print(code,'parse_fail'); continue
    can=Chem.MolToSmiles(m, canonical=True)
    metrics={
        'code':code,'canonical':can,'len':len(can),'mw':round(Descriptors.MolWt(m),1),'logp':round(Crippen.MolLogP(m),2),'tpsa':round(rdMolDescriptors.CalcTPSA(m),1),'qed':round(QED.qed(m),3),'rotors':Lipinski.NumRotatableBonds(m),'rings':rdMolDescriptors.CalcNumRings(m),'heavy':m.GetNumHeavyAtoms(),'hbd':Lipinski.NumHDonors(m),'hba':Lipinski.NumHAcceptors(m),'sa':round(sascorer.calculateScore(m),2) if sascorer else None}
    flags=[]
    if metrics['mw']>700: flags.append('mw')
    if metrics['logp']>8.5: flags.append('logp')
    if not 20<=metrics['tpsa']<=150: flags.append('tpsa')
    if metrics['rotors']>10: flags.append('rotors')
    if metrics['rings']>8: flags.append('rings')
    if metrics['heavy']>58: flags.append('heavy')
    if metrics['sa'] and metrics['sa']>4.9: flags.append('sa')
    metrics['flags']=flags
    print(json.dumps(metrics, sort_keys=True))
PY"

